# inspect components of current test using same routine
h,w=len(test),len(test[0]); bg=collections.Counter(v for row in test for v in row).most_common(1)[0][0]; seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if test[r][c]==bg or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c));co=[]
  while q:
   y,x=q.pop();co.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<h and 0<=xx<w and test[yy][xx]!=bg and (yy,xx) not in seen:seen.add((yy,xx));q.append((yy,xx))
  comps.append(co)
print([(len(c), (min(r for r,x in c),max(r for r,x in c),min(x for r,x in c),max(x for r,x in c)), collections.Counter(test[r][x] for r,x in c)) for c in comps])
